// twilight garden backdrop
const bg=ctx.createLinearGradient(0,0,960,548);bg.addColorStop(0,'#28304a');bg.addColorStop(.52,'#293044');bg.addColorStop(1,'#20293b');ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
// softly glowing moon and mist
