// background stars/fireflies
for(let i=0;i<38;i++){let x=(i*173+39)%940+8,y=(i*97+21)%520+10;ctx.globalAlpha=.19+(Math.sin(performance.now()/700+i)*.15);ctx.fillStyle=i%3?'#dce4ff':'#ffb9d8';ctx.beginPath();ctx.arc(x,y,i%4===0?1.8:1,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;
// garden trees, bushes, flowers
for(let i=0;i<18;i++){let x=(i*127+32)%940+10,y=(i*191+17)%520+8;if(pointOnPath(x,y,68))continue;ctx.fillStyle='#15243866';ctx.beginPath();ctx.arc(x,y,16+(i%4)*3,0,Math.PI*2);ctx.fill();ctx.fillStyle=i%3===0?'#d88ac733':'#7fcdb22b';ctx.beginPath();ctx.arc(x-3,y-3,11+(i%3)*2,0,Math.PI*2);ctx.fill();ctx.fillStyle='#f9c4e266';for(let j=0;j<3;j++){ctx.beginPath();ctx.arc(x+(j-1)*7,y+Math.sin(j)*4,2,0,Math.PI*2);ctx.fill()}}
// route shadow and golden trail
ctx.lineJoin='round';ctx.lineCap='round';ctx.beginPath();route.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));ctx.strokeStyle='#11182766';ctx.lineWidth=65;ctx.stroke();ctx.strokeStyle='#877552';ctx.lineWidth=52;ctx.stroke();ctx.strokeStyle='#c9a975';ctx.lineWidth=42;ctx.stroke();ctx.strokeStyle='#e3c88f';ctx.lineWidth=3;ctx.setLineDash([3,12]);ctx.stroke();ctx.setLineDash([]);
// route side flowers / small lanterns
for(let d=40;d<distances.at(-1)-35;d+=82){let p=pointAt(d),i=Math.floor(d/82),off=i%2?34:-34;let seg=route.findIndex((_,j)=>j>0&&d<=distances[j]);let dx=route[seg][0]-route[seg-1][0],dy=route[seg][1]-route[seg-1][1],l=Math.hypot(dx,dy);let x=p.x-dy/l*off,y=p.y+dx/l*off;if(x>8&&x<W-8&&y>8&&y<H-8){ctx.fillStyle='#ffd99488';ctx.shadowColor='#ffd994';ctx.shadowBlur=12;ctx.beginPath();ctx.arc(x,y,3,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0}}
// academy gate
ctx.save();ctx.translate(902,440);ctx.fillStyle='#412e4f';roundedRect(ctx,-27,-25,54,49,9);ctx.fill();ctx.strokeStyle='#e6a3d8';ctx.lineWidth=3;roundedRect(ctx,-22,-21,44,40,7);ctx.stroke();ctx.fillStyle='#ffd8ef';ctx.font='22px sans-serif';ctx.textAlign='center';ctx.fillText('✧',0,8);ctx.fillStyle='#ffe9be';ctx.font='bold 10px sans-serif';ctx.fillText('GATE',0,39);ctx.restore();
// entry marker
ctx.fillStyle='#b899e9';ctx.font='bold 10px sans-serif';ctx.textAlign='center';ctx.fillText('HOLLOW ENTRY',43,82);
// range preview
if(selected&&pointer){ctx.beginPath();ctx.arc(pointer.x,pointer.y,heroes[selected].range,0,Math.PI*2);ctx.fillStyle=heroes[selected].color+'12';ctx.fill();ctx.strokeStyle=heroes[selected].color+'88';ctx.setLineDash([7,6]);ctx.lineWidth=2;ctx.stroke();ctx.setLineDash([]);ctx.beginPath();ctx.arc(pointer.x,pointer.y,17,0,Math.PI*2);ctx.fillStyle=pointOnPath(pointer.x,pointer.y,38)?'#ff718533':'#fff8';ctx.fill();}
// guardians
for(const t of towers){let h=heroes[t.type];ctx.save();ctx.translate(t.x,t.y);ctx.beginPath();ctx.arc(0,0,h.range,0,Math.PI*2);ctx.fillStyle=h.color+'08';ctx.fill();ctx.strokeStyle=h.color+'25';ctx.lineWidth=1;ctx.stroke();ctx.shadowColor=h.color;ctx.shadowBlur=13;ctx.fillStyle='#151a2a';ctx.beginPath();ctx.arc(0,0,19,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.strokeStyle=h.color;ctx.lineWidth=2;ctx.stroke();ctx.font='23px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(h.emoji,0,1);ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(14,-15,4,0,Math.PI*2);ctx.fill();ctx.restore()}
// enemies
for(const e of enemies){let p=pointAt(e.d);ctx.save();ctx.translate(p.x,p.y+Math.sin(e.phase)*3);ctx.shadowColor=e.fast?'#c088ff':'#9b85ee';ctx.shadowBlur=17;ctx.fillStyle=e.fast?'#d097ff':'#9c8be4';ctx.beginPath();ctx.arc(0,0,e.r,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#342c58';ctx.beginPath();ctx.arc(-4,-2,2,0,Math.PI*2);ctx.arc(4,-2,2,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#eee1ff';ctx.lineWidth=1;ctx.beginPath();ctx.arc(0,2,3,.15,Math.PI-.15);ctx.stroke();ctx.fillStyle='#232236';roundedRect(ctx,-13,-e.r-11,26,4,2);ctx.fill();ctx.fillStyle=e.slow>0?'#83eaf4':'#f186b7';roundedRect(ctx,-13,-e.r-11,26*Math.max(0,e.hp/e.max),4,2);ctx.fill();ctx.restore()}
