}
let pointer=null;function pos(ev){const r=canvas.getBoundingClientRect();return{x:(ev.clientX-r.left)/r.width*W,y:(ev.clientY-r.top)/r.height*H}}
canvas.addEventListener('pointermove',ev=>{pointer=pos(ev)});canvas.addEventListener('pointerleave',()=>pointer=null);canvas.addEventListener('pointerdown',ev=>{const p=pos(ev);if(selected){place(p.x,p.y);return}let t=[...towers].reverse().find(a=>distance(a,p)<23);if(t){let h=heroes[t.type];gold+=Math.round(h.cost*.55);towers=towers.filter(x=>x!==t);notify(`${h.name} recalled · partial stardust refunded`);ui()}});
document.querySelectorAll('.hero-card').forEach(el=>el.addEventListener('click',()=>{let type=el.dataset.hero;if(gold<heroes[type].cost){notify('Not enough stardust!');return}selected=selected===type?null:type;$('hint').innerHTML=selected?`<span>${heroes[type].name.toUpperCase()} SELECTED</span> · tap an empty patch of grass to deploy`:'<span>CHOOSE A GUARDIAN</span> from the right, then place her on the field';ui()}));
$('waveBtn').addEventListener('click',startControl);$('overlayStart').addEventListener('click',startWave);$('pauseBtn').addEventListener('click',()=>{if(!waveActive)return;paused=!paused;$('pauseBtn').textContent=paused?'▶ Resume':'Ⅱ Pause'});$('speedBtn').addEventListener('click',()=>{speed=speed===1?1.5:speed===1.5?2:1;$('speedBtn').textContent=`▶ ${speed}×`});$('resetBtn').addEventListener('click',()=>{reset();notify('Formation reset.')});$('clearBtn').addEventListener('click',()=>{selected=null;$('hint').innerHTML='<span>CHOOSE A GUARDIAN</span> from the right, then place her on the field';ui()});$('helpBtn').addEventListener('click',()=>notify('Choose a guardian · place off the road · start waves · recall by tapping her.'));$('soundBtn').addEventListener('click',ev=>{ev.currentTarget.textContent=ev.currentTarget.textContent==='♫'?'♪':'♫';notify('Ambient audio '+(ev.currentTarget.textContent==='♫'?'on':'off')+' (visual effects only).')});
function frame(t){let dt=Math.min(.05,(t-last)/1000||0);last=t;update(dt);draw();requestAnimationFrame(frame)}ui();requestAnimationFrame(frame);
</script>
</body>
</html>

